/**
 * @distilled.cloud/steel -- Steel browser API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI document mirrored at
 * `specs/spec-mirror-steel/specs/openapi.json`. Everything else in this
 * folder is hand-written.
 *
 * One module per API area: `sessions`, `browserTools`, `files`, `captchas`,
 * `credentials`, `extensions`, `profiles`, `projects`, `apiKeys` and `auth`.
 *
 * @example
 * ```ts
 * import * as Steel from "@distilled.cloud/steel";
 *
 * const session = yield* Steel.sessions.createSession({ blockAds: true });
 * ```
 */
